-- INSERT preguntas PIR 2023 (convocatoria FSE 2023, Psicología)
-- Fuente: Cuaderno_2023_P_0_C.pdf + Plantilla_Respuestas_FSE_v2.xlsx
-- Generado: 206 preguntas validas de 210 impresas (4 anuladas/en blanco excluidas: 71, 104, 159, 174)
-- especialidad/tema quedan NULL: se clasificaran en un paso posterior.

BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.preguntas WHERE "año" = 2023) THEN
    RAISE EXCEPTION 'Ya existen preguntas del año 2023 en la tabla preguntas — abortando para evitar duplicados.';
  END IF;
END $$;


COMMIT;

