INSERT INTO public.preguntas
  ("año", numero, especialidad, pregunta, opcion_a, opcion_b, opcion_c, opcion_d, opcion_e, correcta, imagen_path, tema)
VALUES
  (2023, 1, NULL, 'En relación con los procesos de discriminación y generalización, ¿cuál es la respuesta correcta?:', 'Los estímulos discriminativos no están sujetos al proceso de generalización.', 'La generalización de un estímulo va aumentando a medida que el sujeto es expuesto a reforzamiento diferencial ante variaciones de dicho estímulo.', 'Que el hecho de generalizar o discriminar sea más adaptativo depende de las exigencias del ambiente.', 'Cuanto mayor sea nuestra generalización, más fino será nuestro ajuste al medio.', NULL, 'c', NULL, NULL),
  (2023, 2, NULL, 'Cuando estamos enseñando a un niño pequeño a leer con un libro infantil con grandes dibujos y una frase breve en cada página, al niño le es más fácil aprender sobre los dibujos que sobre las palabras, ¿qué fenómeno de aprendizaje se está produciendo?:', 'Ensombrecimiento.', 'Condicionamiento visual.', 'Generalización.', 'Equivalencia del estímulo.', NULL, 'a', NULL, NULL),
  (2023, 3, NULL, '¿Qué explica el concepto de reactancia psicológica de Brehm?:', 'Explica por qué cumplimos las normas.', 'Hace referencia a por qué a veces tenemos sensación de falta de control.', 'Explica por qué a veces una persona hace lo opuesto a lo que se le pide.', 'Alude a por qué la conducta está motivada por los miedos.', NULL, 'c', NULL, NULL),
  (2023, 4, NULL, '¿Cuál de las siguientes afirmaciones se corresponde con la Teoría del Marcador Somático de A. Damasio (1994)?:', 'El razonamiento no se ve influido por la información emocional.', 'El procesamiento de la emoción depende del procesamiento que se haga de la información somática.', 'El procesamiento emocional depende, en la mayoría de las ocasiones, del hemisferio izquierdo.', 'El procesamiento emocional depende del procesamiento de estímulos llevado a cabo en la glándula pineal.', NULL, 'b', NULL, NULL),
  (2023, 5, NULL, 'Cuando recibimos una descarga eléctrica en un dedo tenemos una sensación desagradable. Si se aumenta la intensidad del estímulo eléctrico al doble, nuestra sensación es más que el doble de desagradable que antes. ¿Cómo se conoce este fenómeno según la Ley de Stevens?:', 'Fenómeno de líneas rectas.', 'Expansión de respuesta.', 'Comprensión de la respuesta.', 'Este fenómeno no lo explica esta teoría.', NULL, 'b', NULL, NULL),
  (2023, 6, NULL, 'Según la hipótesis planteada por Sapir-Whorf, señale la INCORRECTA:', 'El lenguaje no influye en los procesos cognitivos.', 'Esta hipótesis plantea la relación entre pensamiento y lenguaje.', 'El lenguaje puede afectar a los procesos cognitivos.', 'La estructura de una lengua determina la visión del mundo de un hablante nativo.', NULL, 'a', NULL, NULL),
  (2023, 7, NULL, 'María, tras mudarse de piso, sigue pulsando en el ascensor la tecla del 3º (su anterior piso), cuando ahora vive en el 5º. ¿Qué fenómeno relacionado con la memoria explica esta situación?:', 'El número mágico.', 'Interferencia proactiva.', 'Interferencia constructiva.', 'Interferencia retroactiva.', NULL, 'b', NULL, NULL),
  (2023, 8, NULL, 'Respecto a los heurísticos, señale la opción INCORRECTA:', 'Son estrategias generales que usamos para hacer predicciones.', 'Estos procesos de toma de decisiones se enmarcan dentro de los modelos normativos.', 'Pueden realizarse a partir de cálculos de similitud o de recuperación de casos.', 'Dan lugar a errores o sesgos sistemáticos.', NULL, 'b', NULL, NULL),
  (2023, 9, NULL, 'Señala la INCORRECTA respecto a los procesos automáticos:', 'Conllevan bajo consumo de atención.', 'Se ponen en marcha sin necesidad de entrenamiento.', 'No son causa de nuevos aprendizajes.', 'Producen baja interferencia con otros procesos concurrentes.', NULL, 'b', NULL, NULL),
  (2023, 10, NULL, 'Un investigador pasa una prueba de inteligencia a 305 participantes y obtiene que la inteligencia media de la muestra es de 107. El investigador quiere analizar la relación entre velocidad de procesamiento (definida como número de respuestas correctas) e inteligencia (alta y baja). ¿Qué tipo de coeficiente de correlación aplicará el investigador?:', 'Coeficiente de correlación parcial.', 'Coeficiente de correlación biserial.', 'Coeficiente de correlación Phi.', 'Coeficiente de correlación Tetracórica.', NULL, 'b', NULL, NULL),
  (2023, 11, NULL, 'La potencia estadística de un experimento es la probabilidad de que el estudio arroje un resultado significativo si la hipótesis de investigación es verdadera. Señale cuál es la respuesta CORRECTA respecto a los factores que influyen en la potencia estadística:', 'Cuando el tamaño del efecto (d) es grande y el desvío estándar poblacional (σ) es pequeño, aumenta la potencia.', 'Cuando el tamaño de la muestra es pequeño y el desvío estándar poblacional (σ) es grande, aumenta la potencia.', 'Cuando el tamaño de la muestra (n) es grande y el nivel de significación (α) es alto, disminuye la potencia.', 'Cuando el tamaño del efecto (d) es grande y el desvío estándar poblacional (σ) es grande, aumenta la potencia.', NULL, 'a', NULL, NULL),
  (2023, 12, NULL, 'Una ventaja de utilizar la corrección de Bonferroni y el procedimiento HSD de Tukey y otras pruebas post hoc es que:', 'Incrementa la potencia estadística.', 'Disminuye la potencia estadística.', 'Disminuye la probabilidad de cometer un error Tipo II.', 'Disminuye la probabilidad de cometer un error Tipo I.', NULL, 'd', NULL, NULL),
  (2023, 13, NULL, '¿Cuál es el mejor índice de asimetría?:', 'El intercuartílico, por estar basado en índices de posición.', 'El de Pearson, por basarse en los índices de tendencia central.', 'El de Fisher, por tener en cuenta todas las puntuaciones.', 'El coeficiente de variación, por tener en cuenta la variabilidad entre la desviación típica y la media.', NULL, 'c', NULL, NULL),
  (2023, 14, NULL, 'Seleccione la prueba estadística más adecuada para las siguientes dos hipótesis. H1: Las estimaciones de CI de los varones son más elevadas que las de las mujeres. H2: El CI medio de las mujeres es más elevado que el de los varones:', 'H1: Mann-Whitney; H2: t-test para muestras independientes.', 'H1: p (rho) de Spearman; H2: r de Pearson.', 'H1: t-test para muestras relacionadas; H2: Chicuadrado.', 'H1: T de Wilcoxon; H2: Prueba binomial de signos.', NULL, 'a', NULL, NULL),
  (2023, 15, NULL, 'Una de las ventajas de los diseños experimentales con medidas repetidas (comparado con los diseños experimentales con muestras independientes) es:', 'Pérdida de participantes entre las condiciones.', 'Son diseños más económicos en cuanto a los participantes.', 'Efecto de orden.', 'Se necesitan diferentes listas de estímulos.', NULL, 'b', NULL, NULL),
  (2023, 16, NULL, 'De las siguientes afirmaciones, seleccione la CORRECTA. Si en un contraste unilateral derecho utilizamos como nivel de significación 0,005:', 'La probabilidad de mantener H0 siendo falsa es 0,005.', 'La probabilidad de rechazar H0 siendo verdadera es 0,005.', 'La probabilidad de mantener H0 siendo falsa es 0,995.', 'La probabilidad de rechazar H0 siendo verdadera es 0,995.', NULL, 'b', NULL, NULL),
  (2023, 17, NULL, 'Según Beauchamp y Childress (1979), ¿qué principio bioético predominaría en caso de conflicto entre dos o más de ellos?:', 'Justicia.', 'Autonomía.', 'No maleficencia (primum non nocere; ante todo, no hacer daño).', 'Todos los principios obligan por igual al profesional de la Psicología Clínica, quien en caso de conflicto entre dos o más de ellos tendría que evaluar la situación concreta para analizar qué principio pudiera ser prioritario.', NULL, 'd', NULL, NULL),
  (2023, 18, NULL, '¿Cómo se denomina a la relación en la que un profesional de la Psicología Clínica, además de la estrictamente terapéutica, mantiene algún otro tipo de relación con el paciente?:', 'Adicional abusiva.', 'Dual.', 'Sumativa.', 'De poder.', NULL, 'b', NULL, NULL),
  (2023, 19, NULL, 'A qué se refiere el conjunto de características que cada profesional de la Psicología Clínica aplica a cada situación psicoterapéutica, constituyendo sus atributos básicos y que comprende aspectos idiosincrásicos que le empujan a comportarse de un modo particular en el transcurso de su desempeño profesional:', 'Estilo Cognitivo del Terapeuta.', 'Rasgos de Personalidad del Terapeuta.', 'Función Involucración del Terapeuta.', 'Estilo Personal del Terapeuta.', NULL, 'd', NULL, NULL),
  (2023, 20, NULL, 'En la evaluación psicológica, las matrices de interacción y los mapas de conducta son:', 'Escalas de apreciación.', 'Protocolos observacionales de conducta.', 'Procedimientos automáticos de muestreo.', 'Registros narrativos.', NULL, 'b', NULL, NULL),
  (2023, 21, NULL, 'Señale cuál de los siguientes instrumentos específicos para la evaluación del alcoholismo es un test de 10 ítems elaborado por la Organización Mundial de la Salud (OMS) para disponer de una prueba de detección rápida, sencilla, fiable y comparable entre países:', 'AUDIT (Alcohol Use Disorders Identification); Test de Identificación de los Trastornos por Consumo de Alcohol de Babor et al., 1989.', 'ACQ (Alcohol Craving Questionnaire); Cuestionario de Ansia por el Alcohol de Singleton et al., 1996.', 'MALT (Munich Alcoholism Test); Test de Alcoholismo de Munich de Feuerlein et al., 1977.', 'CAGE (The CAGE Questionnaire); El Cuestionario CAGE de Ewing, 1984.', NULL, 'a', NULL, NULL),
  (2023, 22, NULL, 'Cuáles son las características que deben presentar las medidas que van a servir de base para la valoración de un tratamiento psicológico, según Fernández-Ballesteros et al. (2013):', 'Fiabilidad, validez y utilidad.', 'Adecuación, exactitud y fiabilidad.', 'Validez de constructo, eficacia y efectividad.', 'Consistencia interna, objetividad y fiabilidad.', NULL, 'a', NULL, NULL),
  (2023, 23, NULL, '¿Cuál de las siguientes opciones NO es una de las tres dimensiones del carácter del Inventario de Temperamento y Carácter Revisado (TCI-R) de Cloninger?:', 'Autodirección.', 'Persistencia.', 'Cooperación.', 'Autotrascendencia.', NULL, 'b', NULL, NULL),
  (2023, 24, NULL, 'En la evaluación de la esquizofrenia, ¿cuál de los siguientes marcadores psicofisiológicos NO se ha utilizado de modo preferente?:', 'La actividad electrodérmica.', 'Los potenciales evocados.', 'La actividad respiratoria.', 'Los movimientos oculares.', NULL, 'c', NULL, NULL),
  (2023, 25, NULL, '¿Cuál de los siguientes test permite evaluar tanto la personalidad psicopatológica como la personalidad normal?:', 'PAI-A. Inventario de Evaluación de la Personalidad para Adolescentes (Morey).', '16PF-APQ. Cuestionario de Personalidad para Adolescentes 16 PF (Schuerger).', '16PF-5. Cuestionario Factorial de Personalidad (Cattell, Cattell y Cattell).', 'NEO PI-R. Inventario de Personalidad Neo-Revisado (Costa y McCrae).', NULL, 'a', NULL, NULL),
  (2023, 26, NULL, 'Si queremos evaluar la inteligencia de un niño de 7 años, de la manera más breve posible y valorando aspectos verbales y no verbales, ¿cuál de las siguientes pruebas sería la más adecuada?:', 'TONI-4.', 'Escalas de Inteligencia de Reynolds (RIAS).', 'Matrices progresivas de Raven.', 'WISC-V.', NULL, 'b', NULL, NULL),
  (2023, 27, NULL, '¿Cuál de las siguientes afirmaciones es CORRECTA respecto al diagnóstico del TDAH?:', 'Es indispensable aplicar las siguientes pruebas: CARAS-R, D2, ENFEN y SENA.', 'La información aportada por los padres generalmente no se considera fiable.', 'Por cuestiones de eficiencia, sólo es necesario recoger información de la escuela en los casos dudosos.', 'El diagnóstico del TDAH es exclusivamente clínico.', NULL, 'd', NULL, NULL),
  (2023, 28, NULL, 'Una de las siguientes pruebas está diseñada para evaluar lenguaje comprensivo y aporta una medida de cociente intelectual verbal para niños desde los 2 años y 6 meses:', 'Batería del Lenguaje Objetiva y Criterial (BLOC-S-R, Puyuelo M., Renom J., Solanas A. y Wigg E.H., 2007).', 'Test de Comprensión de Estructuras Gramaticales (CEG, Mendoza E., Carballo, G., Muñoz J. y Fresneda, M.D., 2005).', 'Test Boehm de Conceptos Básicos (Boehm, A.E., 2000).', 'Peabody Test (PPVT-III, Dunn L. y Arribas D., 2006).', NULL, 'd', NULL, NULL),
  (2023, 29, NULL, 'Una de las siguientes pruebas está diseñada como screening, con el objeto de identificar aquellas funciones del lenguaje que requieren una evaluación más exhaustiva:', 'Test-Barcelona 2 (Peña-Casanova, 2019).', 'Batería de afasias Western (Kertesz, 2000).', 'Bedside de lenguaje (Sabe et al., 2008).', 'Test de Denominación de Boston (Kaplan et al., 1983).', NULL, 'c', NULL, NULL),
  (2023, 30, NULL, '¿A qué nivel de gravedad del trastorno del espectro del autismo se corresponde, de acuerdo con la clasificación DSM-5, un caso en el que sin ayuda in situ, las deficiencias en la comunicación social causan problemas importantes, con dificultad para iniciar interacciones sociales y con respuestas atípicas o insatisfactorias a la apertura social de otras personas y cuya inflexibilidad de comportamiento causa una interferencia significativa con el funcionamiento en uno o más contextos?:', 'Grado 1.', 'Grado 2.', 'Grado 3.', 'Grado 4.', NULL, 'a', NULL, NULL),
  (2023, 31, NULL, '¿Qué requisito debe presentar un paciente para poder realizar un diagnóstico comórbido de discapacidad intelectual y trastorno del espectro del autismo, según la clasificación DSM-5?:', 'Debe presentar un desempeño en la comunicación social por debajo de lo esperado para el nivel general de desarrollo.', 'Deben existir movimientos, utilización de objetos o habla estereotipados o repetitivos.', 'Debe presentar hiporreactividad ante estímulos sensoriales.', 'Deben confirmarse ambos diagnósticos mediante pruebas psicométricas estandarizadas.', NULL, 'a', NULL, NULL),
  (2023, 32, NULL, 'El inventario de desarrollo Battelle:', 'Incluye las áreas Motora, Adaptativa y Comunicación, pero no Cognitiva.', 'Se utiliza para edades comprendidas entre el nacimiento y los 6 años.', 'Es una escala auto-informada.', 'Se utiliza para edades comprendidas entre el nacimiento y los 8 años.', NULL, 'd', NULL, NULL),
  (2023, 33, NULL, 'Un bebé empieza a presionar un juguete reproduciendo un sonido llamativo. Según los estadios del desarrollo de la inteligencia sensorio-motriz de Piaget, sería un ejemplo de comportamiento del:', 'Estadio 2: Primeras reacciones adquiridas y reacciones circulares primarias.', 'Estadio 3: Reacciones circulares secundarias.', 'Estadio 4: Coordinación de esquemas secundarios y su aplicación a situaciones nuevas.', 'Estadio 5: Reacciones circulares terciarias.', NULL, 'b', NULL, NULL),
  (2023, 34, NULL, 'Señale la opción INCORRECTA respecto a las principales manifestaciones del egocentrismo intelectual en el periodo preoperatorio:', 'Finalismo.', 'Animismo.', 'Realismo.', 'Reversibilidad.', NULL, 'd', NULL, NULL),
  (2023, 35, NULL, 'El reflejo consistente en la extensión de los dedos del pie en forma de abanico, seguida de flexión de los dedos, se conoce como:', 'Babinski.', 'Moro.', 'Patelar.', 'Prensión plantar.', NULL, 'a', NULL, NULL),
  (2023, 36, NULL, 'Según Vygotski, el lenguaje interno:', 'Precede en el desarrollo del niño al lenguaje social.', 'Suele empezar a utilizarse aproximadamente hacia los 10 años.', 'Tiene una función de planificación y regulación de la propia conducta.', 'Tiene una ordenación gramatical similar a la del lenguaje social.', NULL, 'c', NULL, NULL),
  (2023, 37, NULL, 'Mary Ainsworth diseñó un procedimiento de laboratorio, denominado “La situación extraña”, mediante el cual se estudiaba el apego de niños entre 12 y 18 meses. Cuando se producía el reencuentro con la figura de apego en dicha prueba, aquellos niños que se interesaban más por los juguetes que por retomar el contacto con esta figura, podrían ser clasificados como apego:', 'Evitativo (Tipo A).', 'Ambivalente (Tipo C).', 'Desorganizado (Tipo D).', 'Seguro (Tipo B).', NULL, 'a', NULL, NULL),
  (2023, 38, NULL, 'Señale la respuesta CORRECTA respecto al paradigma de la “cara inmóvil” de Tronick:', 'Es un procedimiento de investigación que se emplea para medir la regulación mutua en lactantes.', 'Es una teoría sobre el autismo que permite explicar las dificultades de teoría de la mente que presentan.', 'Tiene como limitación que no explica la transmisión intergeneracional del trauma.', 'Solo se ha comprobado en culturas occidentales.', NULL, 'a', NULL, NULL),
  (2023, 39, NULL, 'El juego funcional es un nivel del juego que:', 'Implica el uso de la función simbólica.', 'Es el más común en niños en edad escolar.', 'Implica el uso de objetos o materiales para formar algo, como una torre con cartas.', 'Supone la práctica repetida en movimientos musculares amplios, como rodar una pelota.', NULL, 'd', NULL, NULL),
  (2023, 40, NULL, 'En el estudio de la personalidad, ¿qué método tiene al análisis factorial como la metodología estadística más utilizada?:', 'El método clínico.', 'La metodología cualitativa.', 'El método correlacional.', 'El método experimental.', NULL, 'c', NULL, NULL),
  (2023, 41, NULL, '¿Qué plantea la Teoría de los Constructos Personales de Kelly (1955)?:', 'Que las atribuciones internas, estables y generales de los fracasos promueven la depresión.', 'Que, a la hora de resolver problemas, la gente no emplea ni sistemas lógicos ni reglas formales de inferencia, sino modelos mentales más sencillos, prácticos y situacionales.', 'Que las personas se definen por rasgos cuantitativos, bipolares o unipolares, generales, transituacionales y analíticos.', 'Que los procesos cognitivos son activos, y que conocer consiste en organizar e integrar información que se está recibiendo continuamente, pero de forma idiosincrásica e individual.', NULL, 'd', NULL, NULL),
  (2023, 42, NULL, '¿Qué repercusiones tiene la discrepancia entre distintos dominios de la identidad, o guías del yo, según la Teoría de la Auto-discrepancia de Higgins (1987)?:', 'Una discrepancia entre la identidad real (o “Yo Real”) y la identidad ideal (o “Yo Ideal”) se relaciona con la depresión.', 'Una discrepancia entre la identidad real (o “Yo Real”) y la identidad obligatoria (o “Yo que Debería”) se relaciona con la vergüenza.', 'Una discrepancia entre la identidad obligatoria (o “Yo que Debería”) y la identidad asumida (o “Yo que me Asigno”) se relaciona con la motivación de logro.', 'Una discrepancia entre la identidad real (o “Yo Real”) y la identidad posible (o “Yo Potencial”) se relaciona con la frustración.', NULL, 'a', NULL, NULL),
  (2023, 43, NULL, 'Fredrickson y Losada (2005) hablan de una ratio de «positividad» que puede ser representada como el cociente entre las emociones positivas y negativas (EP/EN). ¿Qué postulan estos autores?:', 'Que debería haber un equilibrio entre emociones positivas y negativas en una proporción de 1:1.', 'Que las personas son naturalmente optimistas y alegres («sesgo de positividad») por lo que esta ratio tenderá naturalmente a ser el doble de emociones positivas que de negativas; es decir, una proporción de 2:1.', 'Que las personas tienden a sentirse solo ligeramente felices («sesgo de negatividad») por lo que, para lograr un funcionamiento óptimo, las emociones positivas deberían superar a las negativas en una proporción de 3:1.', 'Que las personas con emociones negativas suelen tener más posibilidades de supervivencia por lo que, para lograr un funcionamiento óptimo, las emociones negativas deberían superar a las positivas en una proporción de 1:2.', NULL, 'c', NULL, NULL),
  (2023, 44, NULL, 'Respecto a las investigaciones que estudian la similitud genética y fenotípica en personalidad, usando las correlaciones con los Cinco Grandes rasgos de personalidad entre gemelos monocigóticos (MC) y dicigóticos (DC), podemos concluir que:', 'Las correlaciones en MC son más altas que en DC, lo que apoya la importancia de la influencia genética en estas dimensiones de personalidad.', 'Las similitudes en las correlaciones que se dan en gemelos MC son debidas a influencias ambientales no compartidas.', 'Los estudios con gemelos MC y DC han demostrado fehacientemente que no existen influencias genéticas en la personalidad y que las tendencias de respuesta son aprendidas.', 'Las correlaciones en neuroticismo para gemelos MC son máximas, lo que implica que este rasgo está exclusivamente influenciado por factores genéticos.', NULL, 'a', NULL, NULL),
  (2023, 45, NULL, '¿Qué indican los estudios longitudinales sobre la estabilidad de las cinco grandes dimensiones de personalidad a lo largo de la vida?:', 'Un 51% de la población no cambia su personalidad, un 35% la cambia algo y un 14% la cambia mucho.', 'La correlación de los rasgos de personalidad en los mismos sujetos, medidos en momentos temporales diferentes, permanece muy estable a lo largo de la vida.', 'Las personas muy extravertidas de jóvenes tienen alto neuroticismo de adultas.', 'Las personas son muy conscientes de los cambios en su personalidad y de que hay una correlación muy alta entre la percepción de cambio y el cambio objetivo.', NULL, 'b', NULL, NULL),
  (2023, 46, NULL, 'Los planteamientos socio-cognitivos sobre el estudio de la personalidad:', 'Son criticados porque no tienen en cuenta aspectos como los valores, intereses, metas y proyectos vitales de las personas.', 'Se focalizan en el modo en que la persona elabora y maneja cada situación particular, en lugar de inferir los rasgos que tiene generalmente.', 'Sostienen que los rasgos pueden predecir el comportamiento de individuos concretos en circunstancias concretas.', 'Sostienen que las personas extravertidas lo son porque se comportan de modo extravertido en todas las situaciones.', NULL, 'b', NULL, NULL),
  (2023, 47, NULL, '¿Cuál de las siguientes afirmaciones sobre el modelo de capacidades mentales primarias de Thurstone es CORRECTA?:', 'Confirma la existencia del factor G de inteligencia del modelo bifactorial de Spearman.', 'Considera que la Rapidez Perceptiva es la habilidad necesaria para la realización de aquellos procesos de razonamiento que van de lo específico a lo general.', 'Postula la existencia de once factores independientes entre sí.', 'Se basa, del mismo modo que el modelo de Spearman, en el análisis factorial.', NULL, 'd', NULL, NULL),
  (2023, 48, NULL, 'Señale la respuesta CORRECTA sobre el modelo de inteligencia Cattell-Horn:', 'La morfología de la inteligencia se podría representar a partir de un cubo tridimensional general formado por 120 cubos pequeños o «aptitudes mentales independientes».', 'Es un modelo no jerárquico que confirma la teoría bifactorial de Spearman.', 'Existen una serie de factores de primer orden como la «inteligencia fluida (Gf)», la «inteligencia cristalizada (Gc)», la «inteligencia visual (Gv)», la «capacidad de recuperación (Gr)» y la «velocidad cognitiva (Gs)».', 'Tendríamos dos factores de tercer orden: La inteligencia fluida histórica (Gf-h) y un factor de aprendizaje común (Se).', NULL, 'd', NULL, NULL),
  (2023, 49, NULL, '¿Cuál de las siguientes definiciones sobre las dimensiones del modelo de los Cinco Grandes factores es CORRECTA?:', 'Un individuo con alta puntuación en neuroticismo tendrá tendencia a sentirse seguro de sí mismo.', 'La extraversión evalúa la búsqueda activa y el aprecio por la experiencia, la tolerancia y exploración de lo no familiar.', 'Un individuo con baja puntuación en apertura a la experiencia será curioso, imaginativo y poco tradicional.', 'La voluntad y minuciosidad diferencia a las personas serias y formales de las informales y descuidadas.', NULL, 'd', NULL, NULL),
  (2023, 50, NULL, '¿Cuál de las siguientes se considera una de las principales aportaciones de Francis Galton al estudio de la Psicología Diferencial?:', 'La sistematización conceptual contemporánea de la disciplina.', 'El uso del tiempo de reacción para medir variables como la atención, la fatiga o los efectos de la práctica.', 'El desarrollo del método sustractivo, origen de la cronometría mental.', 'La creación de pruebas y estrategias de evaluación para obtener medidas directas de las funciones mentales.', NULL, 'd', NULL, NULL),
  (2023, 51, NULL, '¿Con qué nombre se conoce al concepto que alude al conjunto de costumbres, sentimientos e ideales que hacen relativamente estables y predecibles las reacciones de un individuo?:', 'Carácter.', 'Temperamento.', 'Constitución.', 'Estilo cognitivo.', NULL, 'a', NULL, NULL),
  (2023, 52, NULL, 'En el estudio de la inteligencia, ¿con qué nombre se conoce al tiempo mínimo necesario que tarda una persona en reconocer correctamente un estímulo que es presentado durante un período temporal muy breve?:', 'Tiempo de reacción simple.', 'Tiempo de reacción de elección.', 'Tiempo de inspección.', 'Tiempo de decisión.', NULL, 'c', NULL, NULL),
  (2023, 53, NULL, 'Sobre la Escala de Comprobación de Psicopatía Revisada (PCL-R) de Robert Hare, estudios factoriales arrojaron la existencia de 2 factores. ¿Cuál de estos ítems NO forma parte de ninguno de los dos factores?:', 'Estilo de vida parasitario.', 'Impulsividad.', 'Problemas de conducta tempranos.', 'Maquiavelismo.', NULL, 'd', NULL, NULL),
  (2023, 54, NULL, 'Señale cuál de los siguientes criterios diagnósticos NO forma parte del trastorno de la personalidad esquizotípica según el DSM-5:', 'No tiene amigos íntimos ni confidentes aparte de sus familiares de primer grado.', 'Comportamiento o aspecto extraño, excéntrico o peculiar.', 'No desea ni disfruta las relaciones íntimas, incluido el formar parte de una familia.', 'Ansiedad social excesiva que no disminuye con la familiaridad y tiende a asociarse a miedos paranoides más que a juicios negativos sobre sí mismo.', NULL, 'c', NULL, NULL),
  (2023, 55, NULL, '¿Cuál de los siguientes NO es un tipo de demencia frontotemporal?:', 'Afasia progresiva primaria no fluente.', 'Afasia progresiva primaria fluente, variante semántica (antes llamada demencia semántica).', 'Demencia frontotemporal variante conductual.', 'Síndrome CADASIL (Cerebral Autosomal Dominant Arteriopathy with Subcortical Infarcts and Leukoencephalopathy).', NULL, 'd', NULL, NULL),
  (2023, 56, NULL, 'Solicitan nuestra valoración para un paciente con daño cerebral y síndrome disejecutivo que presenta importante irritabilidad, desinhibición sexual y grave impulsividad. Dentro de la clasificación de síndromes disejecutivos en función de la topografía de la lesión ¿qué zona del lóbulo frontal estaría más afectada?:', 'Dorsolateral.', 'Orbital.', 'Cingulada.', 'Motora suplementaria.', NULL, 'b', NULL, NULL),
  (2023, 57, NULL, 'En la demencia con cuerpos de Lewy, el perfil neuropsicológico típico implica:', 'Problemas visoespaciales y en funciones ejecutivas, especialmente en cambio atencional o shifting.', 'Problemas mnésicos graves desde el inicio, pero únicamente en memoria episódica.', 'Problemas mnésicos graves desde el inicio, pero únicamente en memoria semántica.', 'Bradicinesia, compulsividad y apatía.', NULL, 'a', NULL, NULL),
  (2023, 58, NULL, '¿Cómo se produce la mielina en el Sistema Nervioso Central (SNC) y en el Sistema Nervioso Periférico (SNP)?:', 'En el SNC se produce por los neurotransmisores y en el SNP por las hormonas.', 'En el SNC se produce por los oligodendrocitos y en el SNP por las células de Schwann.', 'En ambos casos se produce directamente por los axones de las neuronas.', 'En el SNC se produce en los nódulos de Ranvier y en el SNP directamente por los axones de la propia neurona.', NULL, 'b', NULL, NULL),
  (2023, 59, NULL, '¿Cuál de estas áreas del Sistema Nervioso Central es irrigada en su mayor parte por la arteria basilar?:', 'La rodilla del cuerpo calloso.', 'Los lóbulos frontales.', 'El tallo cerebral.', 'Los lóbulos parietales.', NULL, 'c', NULL, NULL),
  (2023, 60, NULL, 'La vía cerebral que participa en el procesamiento del movimiento y la percepción espacial:', 'Se llama vía parvocelular o vía P.', 'Es una vía que proyecta desde el lóbulo occipital a áreas temporales inferiores.', 'Comienza y termina en la corteza estriada del lóbulo occipital.', 'Se proyecta desde el lóbulo occipital hasta el lóbulo parietal.', NULL, 'd', NULL, NULL),
  (2023, 61, NULL, '¿Cuál es el mecanismo de acción del metilfenidato respecto a la dopamina?:', 'Se ha demostrado que el metilfenidato no influye en la vía dopaminérgica y que su mecanismo de acción se da únicamente en la vía noradrenérgica.', 'Inhibe la liberación de dopamina en la hendidura sináptica.', 'Bloquea los transportadores de dopamina, lo que reduce la recaptación sináptica y aumenta la concentración extraneuronal de dopamina.', 'Aumenta la recaptación sináptica, lo que provoca una disminución de la concentración extraneuronal de dopamina.', NULL, 'c', NULL, NULL),
  (2023, 62, NULL, '¿A qué se refiere la APA (2006) con la integración de la mejor evidencia disponible con la pericia clínica en el contexto de las características, cultura y preferencias del paciente?:', 'A la Práctica Basada en la Evidencia.', 'A la Evidencia Basada en la Práctica.', 'A la Práctica Deliberada.', 'A la Práctica Reflexiva.', NULL, 'a', NULL, NULL),
  (2023, 63, NULL, 'Según Anderson et al. (2009) la fluidez verbal, la calidez, la empatía, la expresión emocional, la capacidad persuasiva, la capacidad para instilar esperanza, la capacidad para la vinculación y para comprender el problema presentado por el paciente:', 'No se ha encontrado relación entre ellas y la eficacia de los especialistas en Psicología Clínica (Supershrinks).', 'Constituyen habilidades de facilitación interpersonal.', 'La edad de los profesionales no correlaciona positivamente con la presencia de estas habilidades.', 'Forman parte del concepto de Práctica Reflexiva de Bennett-Levy.', NULL, 'b', NULL, NULL),
  (2023, 64, NULL, 'En referencia a los trastornos del habla, señale cuál de las opciones de respuesta se corresponde con la definición de disartria:', 'Trastorno de la capacidad para pronunciar correctamente determinados fonemas o grupos de fonemas.', 'Trastorno de la articulación o del control muscular del habla, secundario a un déficit neurológico.', 'Trastorno de la pronunciación determinado por problemas estructurales del aparato bucofonatorio.', 'Trastorno del habla caracterizado por tropiezos, espasmos y repeticiones debido a una coordinación imperfecta de las funciones ideomotrices cerebrales.', NULL, 'b', NULL, NULL),
  (2023, 65, NULL, 'En relación con la Escala de gravedad de los síntomas de las dimensiones de psicosis, incluida en la Sección III del DSM-5:', 'Es una escala auto-aplicada.', 'Evalúa la gravedad de los síntomas en los 7 días anteriores.', 'Evalúa 5 dominios: Alucinaciones, Delirios, Discurso desorganizado, Comportamiento psicomotor anormal y Comportamiento adaptativo.', 'No tiene en cuenta la gravedad del deterioro cognitivo.', NULL, 'b', NULL, NULL),
  (2023, 66, NULL, 'La Economía Conductual plantea la adicción como un trastorno de la elección caracterizado por la “patología del refuerzo”. Dentro de esto, ¿a qué se llama el “descuento por demora” (o Delay Discounting)?:', 'A la preferencia excesiva por reforzadores de mayor intensidad frente a los de menor intensidad.', 'A la preferencia excesiva por reforzadores inmediatos frente a los demorados.', 'A la preferencia excesiva por reforzadores más salientes frente a los menos salientes.', 'A la preferencia excesiva por reforzadores más numerosos, aunque menos intensos, frente a los menos numerosos, aunque más intensos.', NULL, 'b', NULL, NULL),
  (2023, 67, NULL, 'En relación con la evidencia empírica del manejo de contingencias en la intervención en cannabis, los estudios clínicos aleatorizados han mostrado mejores resultados cuando se dirige a:', 'Reforzar la abstinencia.', 'Reforzar otras conductas de adherencia al tratamiento (realización de analíticas de orina o asistencia a las sesiones).', 'Reforzar la realización de las tareas para casa.', 'Reforzar una comunicación positiva con otros miembros de la familia.', NULL, 'a', NULL, NULL),
  (2023, 68, NULL, '¿Cuál de las siguientes NO es una terapia de eficacia probada (grado de recomendación A) para la adicción al alcohol?:', 'Intervenciones motivacionales breves.', 'Terapia conductual familiar y de pareja.', 'Aproximación de reforzamiento comunitario (Community Reinforcement Approach– CRA).', 'Terapia de exposición a señales (Cue Exposure Therapy–CET).', NULL, 'd', NULL, NULL),
  (2023, 69, NULL, 'Al comparar las adicciones a sustancias con las adicciones sin sustancia (adicciones conductuales):', 'En ambos casos se pretende la abstinencia completa.', 'La terapia cognitivo-conductual ha demostrado eficacia en las adicciones a sustancias, pero no en las adicciones conductuales.', 'Las adicciones conductuales y los trastornos por abuso de sustancias responden a menudo de manera positiva a los mismos tratamientos.', 'No se espera que la investigación en las adicciones a sustancias favorezca la comprensión de las adicciones conductuales.', NULL, 'c', NULL, NULL),
  (2023, 70, NULL, '¿Cuál de los siguientes trastornos, incluido dentro de la categoría “Trastorno obsesivo-compulsivo y trastornos relacionados” (DSM-5 y CIE-11), fue clasificado en versiones anteriores de ambos manuales en los “Trastornos del control de los impulsos”?:', 'Trastorno de acumulación.', 'Excoriación.', 'Tricotilomanía.', 'Trastorno dismórfico corporal.', NULL, 'c', NULL, NULL),
  (2023, 72, NULL, 'Respecto a las denominadas “obsesiones puras”:', 'Aparecen en personas que se encuentran en fases tempranas o muy avanzadas del trastorno obsesivo compulsivo.', 'En las primeras fases del desarrollo del trastorno obsesivo compulsivo las obsesiones se evidencian antes que las compulsiones.', 'Pueden asociarse a una comprensión del problema (insight) muy precaria y otras dificultades metacognitivas.', 'No se considera actualmente una terminología adecuada, pudiendo generar errores de diagnóstico y tratamiento.', NULL, 'd', NULL, NULL),
  (2023, 73, NULL, '¿Cuál de las siguientes estrategias de supresión de las obsesiones es la más característica de las personas con trastorno obsesivo-compulsivo?:', 'Distracción.', 'Control social.', 'Autocastigarse.', 'Preocupación.', NULL, 'c', NULL, NULL),
  (2023, 74, NULL, 'En relación con el nivel de insight que la persona con trastorno obsesivo-compulsivo tiene sobre sus síntomas:', 'Un nivel de insight bajo se asocia a mayor comorbilidad con otros problemas.', 'El nivel de insight es menor cuando se presentan contenidos obsesivos de simetría, orden y limpieza.', 'El nivel de insight es una característica estable a lo largo de la evolución del trastorno.', 'El inicio tardío de los síntomas se asocia a un nivel de insight bajo.', NULL, 'a', NULL, NULL),
  (2023, 75, NULL, 'La “sensación de conocer” es una distorsión de la memoria clasificada como:', 'Paramnesia del recuerdo.', 'Paramnesia del reconocimiento.', 'Parapraxia del recuerdo.', 'Parapraxia del reconocimiento.', NULL, 'c', NULL, NULL),
  (2023, 76, NULL, 'En el trastorno obsesivo-compulsivo, la “verificación o comprobación compulsiva” ha sido explicada por Radomsky et al. (2006) como:', 'Originada en la muy baja confianza en la propia memoria del verificador y la repetición del propio comportamiento verificado.', 'Resultado de la disminución de efecto de recencia generada por los comportamientos repetitivos, dificultando el recuerdo de los hechos recientes.', 'Asociada a la calidad del recuerdo, producto de la tendencia a la memoria visual de los comprobadores compulsivos.', 'Un error en la ordenación temporal del propio recuerdo durante la codificación de las actividades repetitivas.', NULL, 'a', NULL, NULL),
  (2023, 77, NULL, 'Entre las esteroagnosias, las dificultades para reconocer las sensaciones corporales internas, como por ejemplo la percepción de la temperatura corporal, se denomina:', 'Agnosia para los objetos.', 'Anosognosia.', 'Somatoagnosia.', 'Autotopagnosia.', NULL, 'c', NULL, NULL),
  (2023, 78, NULL, 'La amnesia global transitoria es una pérdida brusca y masiva de recuerdos autobiográficos caracterizada por:', 'Afectar sobre todo a adultos jóvenes, cursar con buen pronóstico y recuperación completa de forma natural y gradual.', 'Alto nivel de recurrencia a lo largo de la vida (entre 25-30%).', 'Presentar una duración de entre una y dos semanas.', 'Frente a otras posibles causas, tienen un peso fundamental la presencia de enfermedades sistémicas o cardiovasculares.', NULL, 'd', NULL, NULL),
  (2023, 79, NULL, 'La depresión doble:', 'Es un trastorno incluido en el DSM-5 para describir condiciones en las que coexiste una depresión mayor y un trastorno depresivo persistente.', 'Es un término empleado en protocolos de investigación.', 'Es un trastorno incluido en el DSM-5 para describir condiciones en las que coexiste una depresión mayor y un trastorno por uso de sustancias.', 'Es un trastorno incluido en la CIE-11 para describir condiciones en las que coexiste una depresión mayor y un trastorno distímico.', NULL, 'b', NULL, NULL),
  (2023, 80, NULL, 'Según el DSM-5, algunas de las diferencias entre la depresión mayor y el trastorno bipolar son:', 'La depresión mayor responde peor al tratamiento antidepresivo convencional que el trastorno bipolar, y se considera que en general tiene más carga genética que éste.', 'El trastorno bipolar está asociado a un menor riesgo de suicidio que el trastorno depresivo mayor.', 'Los trastornos depresivos tienen más episodios de media a lo largo de la vida que los trastornos bipolares.', 'La depresión mayor tiene una prevalencia a los 12 meses del 7% aproximadamente, mientras que el trastorno bipolar tiene una prevalencia durante 12 meses del 0,6 % aproximadamente.', NULL, 'd', NULL, NULL),
  (2023, 81, NULL, 'Señala la opción INCORRECTA sobre el mutismo selectivo:', 'En el DSM-5 se incluye dentro de los trastornos de ansiedad.', 'En la CIE-10 el trastorno se denomina mutismo electivo.', 'En el DSM-5 se incluye dentro de los trastornos del neurodesarrollo.', 'La duración de la alteración es como mínimo de un mes (no limitada al primer mes de escuela).', NULL, 'c', NULL, NULL),
  (2023, 82, NULL, 'El modelo de aprensión ansiosa ha sido propuesto por:', 'Borkovec.', 'Barlow.', 'Semerari.', 'Wells.', NULL, 'b', NULL, NULL),
  (2023, 83, NULL, 'La Teoría de la Indefensión Aprendida de Selligman propone que:', 'El estilo atribucional de la depresión se caracteriza por atribuciones internas, estables y globales para los fracasos o acontecimientos negativos.', 'El mantenimiento de las conductas por refuerzo social y la falta de habilidades sociales como principal determinante de la baja tasa de reforzamiento.', 'La pérdida de autoestima es el eje de la depresión.', 'La capacidad de autorrefuerzo es el eje de la depresión.', NULL, 'a', NULL, NULL),
  (2023, 84, NULL, 'El trastorno de pánico:', 'Tiene una prevalencia anual del 5-7% en la población general.', 'La mujer tiene el triple de probabilidad de desarrollar el cuadro que el hombre.', 'Presenta una elevada comorbilidad con enfermedades físicas y médicas.', 'Presenta una baja comorbilidad con el trastorno bipolar.', NULL, 'c', NULL, NULL),
  (2023, 85, NULL, 'El mayor riesgo de conducta suicida en los trastornos psicóticos se ha descrito en:', 'La fase prodrómica de un episodio psicótico.', 'Los primeros años tras el inicio del trastorno psicótico.', 'Los trastornos psicóticos de larga evolución.', 'Los trastornos psicóticos de inicio tardío (entre los 40 y los 60 años).', NULL, 'b', NULL, NULL),
  (2023, 86, NULL, 'El sesgo cognitivo denominado “salto a las conclusiones”:', 'Se asocia con la presencia de alucinaciones.', 'Se observa en menos de un tercio de los individuos con ideas delirantes.', 'Se asocia con la presencia de ideas delirantes.', 'No se da en la población general.', NULL, 'c', NULL, NULL),
  (2023, 87, NULL, 'Uno de los tratamientos multimodales integrados para la psicosis es:', 'La terapia interpersonal de Fairburn.', 'La terapia interpersonal y de ritmos sociales de Frank.', 'La terapia psicológica integrada de Roder, Müller, Brenner y Spaulding.', 'La terapia interpersonal metacognitiva de Cheli, Lysaker y Dimaggio.', NULL, 'c', NULL, NULL),
  (2023, 88, NULL, 'Respecto al tratamiento psicológico de los trastornos psicóticos:', 'El entrenamiento en habilidades sociales siempre incluye el manejo del abuso de sustancias.', 'Las intervenciones familiares se basan en las necesidades de los familiares del paciente.', 'Las intervenciones familiares se centran en que los familiares asuman el control del tratamiento psicofarmacológico del paciente.', 'El entrenamiento en habilidades sociales incluye la percepción emocional.', NULL, 'd', NULL, NULL),
  (2023, 89, NULL, '¿Cuál de las siguientes es una característica del modelo fenomenológico aplicado a la psicosis?:', 'Se centra en la experiencia subjetiva de la persona y en cómo se relaciona consigo misma, los demás y el mundo.', 'Se centra en los procesos neurobiológicos implicados en el origen y desarrollo de los síntomas psicóticos.', 'Se centra en los procesos de vulnerabilidad y estrés, así como en la interacción de factores biológicos y ambientales.', 'Se centra en un modelo de continuidad que oscila desde los estados no clínicos hasta llegar a los niveles clínicos de síntomas psicóticos con necesidad de tratamiento.', NULL, 'a', NULL, NULL),
  (2023, 90, NULL, 'En relación con los tratamientos psicológicos para los problemas relacionados con traumas y factores de estrés, señale la afirmación INCORRECTA:', 'Las técnicas de exposición prolongada y de reestructuración cognitiva son las más eficaces para reducir los síntomas en víctimas de agresiones sexuales u otros traumas.', 'Entre los tratamientos psicológicos, distinguimos los tratamientos centrados en el trauma y los no centrados en el trauma.', 'El entrenamiento en inoculación de estrés sería un tipo de tratamiento psicológico centrado en el trauma.', 'La terapia de procesamiento cognitivo sería un tipo de tratamiento psicológico centrado en el trauma.', NULL, 'c', NULL, NULL),
  (2023, 91, NULL, '¿A qué experiencia nos referimos cuando una persona nos cuenta que cada vez que ve la foto de su padre comienza a escuchar voces que la insultan?:', 'Alucinación extracampina.', 'Alucinación negativa.', 'Alucinación refleja.', 'Alucinación funcional.', NULL, 'c', NULL, NULL),
  (2023, 92, NULL, '¿Cómo se denomina al fenómeno de pensar de forma perseverante o repetitiva sobre las emociones negativas, los síntomas de malestar y los problemas, así como en sus posibles causas y consecuencias?:', 'Pensamientos automáticos negativos.', 'Rumiación.', 'Preocupaciones.', 'Obsesiones.', NULL, 'b', NULL, NULL),
  (2023, 93, NULL, '¿Cómo se denomina el tipo de alucinaciones en el que se perciben sonidos simples como ruidos, pitidos, cuchicheos o pasos?:', 'Acoasmas.', 'Fonemas.', 'Fotomas.', 'Fantosmias.', NULL, 'a', NULL, NULL),
  (2023, 94, NULL, '¿En cuál de los siguientes cuadros clínicos es más probable que encontremos un síndrome de Cotard?:', 'Demencia frontotemporal.', 'Episodio maníaco.', 'Epilepsia del lóbulo temporal.', 'Episodio depresivo mayor.', NULL, 'd', NULL, NULL),
  (2023, 95, NULL, 'La Psicoterapia Analítico Funcional (FAP) describe 5 reglas que aportan sugerencias para la conducta del terapeuta en sesión. ¿Cuáles son?:', 'Observar, reforzar, observar el efecto del refuerzo, reformular las conductas clínicas e interpretarlas.', 'Observar, evocar, reforzar, observar el efecto del refuerzo e interpretar.', 'Observar, evocar, observar el efecto del refuerzo, interpretar y generar hipótesis alternativas.', 'Observar el efecto del refuerzo, evocar, disminuir conductas clínicamente relevantes tipo 2, aumentar conductas clínicamente relevantes tipo 1 e interpretar.', NULL, 'b', NULL, NULL),
  (2023, 96, NULL, '¿Cuál de las siguientes estrategias forma parte del proceso terapéutico en la Terapia de Aceptación y Compromiso (ACT)?:', 'Fomentar que el paciente pueda fusionarse con sus valores personales.', 'Ayudar al paciente a contactar con su historia personal, así como con los contenidos y reglas que controlan sus actos y sus efectos.', 'Generar en el paciente habilidades para reducir y tratar sus pensamientos aversivos con perspectiva, formulando explicaciones alternativas.', 'Entrenar al paciente en el control de sus eventos privados para que pueda orientarse hacia sus valores personales.', NULL, 'b', NULL, NULL),
  (2023, 97, NULL, 'En relación con el uso de la Terapia Dialéctico Conductual (DBT) en el abordaje de la conducta suicida, ¿cuál de las siguientes afirmaciones es INCORRECTA?:', 'Dentro de la jerarquía de metas terapéuticas, el primer objetivo es abordar las conductas que interfieren con la terapia.', 'Una de las reglas básicas del tratamiento es que la persona que realiza un acto suicida no puede llamar a su terapeuta durante las 24 horas siguientes.', 'Su versión para adolescentes (DBT-A) se ha constituido como el tratamiento psicológico mejor establecido para el abordaje de la conducta suicida en esta población.', 'Dentro de las estrategias de cambio, el análisis en cadena y el análisis de solución destacan por su utilidad en el abordaje de la conducta suicida.', NULL, 'a', NULL, NULL),
  (2023, 98, NULL, '¿A qué tipo de conductas hacen referencia las conductas clínicamente relevantes tipo 3 (CCR3) descritas en la Psicoterapia Analítico Funcional (FAP)?:', 'Conductas del paciente fuera de la sesión que poseen una equivalencia funcional con las observadas en el contexto terapéutico.', 'Conductas del paciente que constituyen una nueva clase funcional y que son ejemplos de mejoría.', 'Conductas, en forma de reglas, que incluyen discriminaciones del paciente sobre su propia conducta y sus elementos de control.', 'Conductas que forman parte de la clase funcional problemática del paciente y que tienen una función de evitación.', NULL, 'c', NULL, NULL),
  (2023, 99, NULL, 'Según el DSM-5, en la autolesión no suicida:', 'El individuo se infringe lesiones superficiales no dolorosas de manera repetida.', 'Lo más habitual es que comience en los primeros años de la edad adulta.', 'El alivio o la respuesta deseada se experimenta durante o poco después de la autolesión.', 'No aumenta el riesgo de contagio de enfermedades de transmisión sanguínea.', NULL, 'c', NULL, NULL),
  (2023, 100, NULL, 'Según la propuesta de O’Connor y Nock (2014), el término conducta suicida se refiere específicamente:', 'A los pensamientos acerca de quitarse la vida.', 'A la formulación del modo de quitarse la vida.', 'Al conjunto de pensamientos y comportamientos relacionados con quitarse intencionadamente la vida.', 'A la participación en un comportamiento potencialmente autodestructivo en el que existe, al menos, alguna intención de morir como resultado del comportamiento.', NULL, 'c', NULL, NULL),
  (2023, 101, NULL, 'Según la CIE-11, el trastorno evitativo o restrictivo de la ingesta alimentaria (TERIA):', 'Incluye el síndrome de pica.', 'Incluye la ingesta de una variedad insuficiente de alimentos para satisfacer los requisitos energéticos o nutricionales adecuados.', 'Está motivado por la preocupación por el peso o la forma corporal.', 'Excluye la dependencia de suplementos nutricionales orales o alimentación por sonda.', NULL, 'b', NULL, NULL),
  (2023, 102, NULL, 'En Psicología de la Salud, el término “Optimismo Irreal” se refiere a:', 'La creencia irracional de que, con los avances de la medicina de hoy en día, cualquier enfermedad es potencialmente curable.', 'Un sesgo cognitivo por el que un individuo se considera a sí mismo con menos probabilidades, en comparación con otros, de desarrollar una enfermedad.', 'La creencia, no contrastada, de que ser optimista se asocia con una mejor evolución y pronóstico de las enfermedades oncológicas.', 'Los mensajes minimizadores sobre la enfermedad que algunas personas transmiten a sus familiares enfermos con el fin de reducir su malestar.', NULL, 'b', NULL, NULL),
  (2023, 103, NULL, 'La Teoría de la Motivación para la Protección fue desarrollada por Rogers (1985) para ampliar el Modelo de Creencias sobre la Salud (MCS) de Becker y Maiman (1975). ¿Cuál es el factor que añade Rogers al MCS?:', 'Miedo a padecer la enfermedad.', 'Susceptibilidad a la enfermedad.', 'Severidad de la enfermedad.', 'Beneficios percibidos de la conducta preventiva.', NULL, 'a', NULL, NULL),
  (2023, 105, NULL, 'Según Miller y Rollnick (2015), los “Procesos” de la Entrevista Motivacional son:', 'Vincular, focalizar, evocar y planificar.', 'Precontemplación, contemplación, acción y mantenimiento.', 'Autoconciencia, autoevaluación y autoliberación.', 'Generar motivación y consolidar el compromiso.', NULL, 'a', NULL, NULL),
  (2023, 106, NULL, '¿Cuáles son las “Tareas de Duelo” que propone Worden (1991; 2013)?:', 'Trabajar la tristeza por la pérdida, adaptarse a un mundo en el que el fallecido está ausente, recolocar emocionalmente al fallecido y continuar viviendo.', 'Ayudar a aceptar la realidad de la pérdida, ayudar a expresar la tristeza y dotar de significado a la pérdida.', 'Shock, anhelo y búsqueda, desorganización y reorganización.', 'Aceptar la realidad de la pérdida, elaborar el dolor, adaptarse a un mundo sin el fallecido y hallar un modo de recordar al fallecido al embarcarse en una nueva vida.', NULL, 'd', NULL, NULL),
  (2023, 107, NULL, 'En la aplicación de la Terapia de Aceptación y Compromiso (ACT) al tratamiento del dolor crónico, ¿qué objetivo tiene la fase de “Desesperanza creativa”?:', 'Ayudar al paciente a percibir la falta de eficacia de sus estrategias para combatir el dolor.', 'Ayudar al paciente a debilitar el contexto verbal/social que controla el dolor.', 'Ayudar al paciente a desarrollar e implementar planes de conducta para cambiar de vida.', 'Ayudar al paciente a establecer un lugar seguro para vivir las experiencias relacionadas con el dolor.', NULL, 'a', NULL, NULL),
  (2023, 108, NULL, '¿Cuáles de los siguientes patrones de afrontamiento del cáncer se han asociado a un menor malestar emocional y más adecuada modulación de la percepción del dolor?:', 'Búsqueda de apoyo social y escape/evitación cognitiva.', 'Centrarse en lo positivo y escape/evitación conductual.', 'Distanciamiento y escape/evitación tanto cognitiva como conductual.', 'Búsqueda de apoyo social, centrarse en lo positivo y distanciamiento.', NULL, 'd', NULL, NULL),
  (2023, 109, NULL, '¿Qué explicación se plantea desde la “Hipótesis de la Amortiguación”?:', 'El apoyo social mejora la salud al incrementar el sentido de responsabilidad sobre la propia vida.', 'El apoyo social mitiga los daños sobre la salud que produce la exposición al estrés.', 'Las personas con buen apoyo social desarrollan menos conductas de riesgo para la salud.', 'El apoyo social facilita la realización de conductas saludables y de autocuidado.', NULL, 'b', NULL, NULL),
  (2023, 110, NULL, '¿En función de qué criterio clasifican Mrazek y Haggerty (1994) las estrategias de prevención de la enfermedad cuando proponen la clasificación de prevención universal, selectiva e indicada?:', 'En función del momento de evolución del problema o enfermedad.', 'En función del tipo de población a la que se dirige la actividad preventiva.', 'En función del tipo de enfermedad que se pretende prevenir.', 'En función del ámbito en el que se desarrolla el programa preventivo.', NULL, 'b', NULL, NULL),
  (2023, 111, NULL, 'Según la OMS (2003), la adherencia terapéutica es:', 'El grado en el que la conducta de un paciente (tomar medicación, seguir una dieta y/o cambios en el estilo de vida) coincide con las instrucciones proporcionadas por el personal sanitario.', 'El grado en el que el comportamiento de una persona (tomar medicación, seguir una dieta y/o cambios en el estilo de vida) se corresponde con lo acordado con el profesional de la salud.', 'Un concepto utilizado preferentemente en investigación.', 'Un concepto en desuso.', NULL, 'b', NULL, NULL),
  (2023, 112, NULL, '¿Qué emparejamiento de autor y aportación teórica es CORRECTO?:', 'Teoría de las relaciones objetales/Sigmud Freud.', 'Sostenimiento emocional (holding)/Donald W. Winnicott.', 'Real, imaginario, simbólico/Melanie Klein.', 'Separación-Individuación/Karen Horney.', NULL, 'b', NULL, NULL),
  (2023, 113, NULL, 'Según Lambert, ¿qué factor de la varianza del cambio terapéutico tiene más peso?:', 'Factores comunes.', 'Factores técnicos.', 'Cambio extra-terapéutico.', 'Expectativas, placebo.', NULL, 'c', NULL, NULL),
  (2023, 114, NULL, '¿Qué terapia propone que en el trastorno límite de la personalidad hay una alteración en la capacidad de dar sentido y comprender el comportamiento propio y ajeno en términos de estados y procesos mentales?:', 'Terapia Dialéctico Conductual.', 'Terapia de Conducta.', 'Terapia Morita.', 'Terapia Basada en la Mentalización.', NULL, 'd', NULL, NULL),
  (2023, 115, NULL, 'Según la CIE-11, la hipocondriasis se encuentra dentro del grupo de:', 'Trastornos de distrés corporal o de la experiencia corporal.', 'Trastornos disociativos.', 'Trastornos de ansiedad o relacionados con el miedo.', 'Trastornos obsesivo-compulsivos y otros trastornos relacionados.', NULL, 'd', NULL, NULL),
  (2023, 116, NULL, '¿Qué modalidad de tratamiento se considera como primera opción en la anorexia nerviosa?:', 'Ingreso hospitalario con separación familiar.', 'Ingreso domiciliario con supervisión familiar.', 'Tratamiento ambulatorio.', 'Recursos de hospitalización parcial.', NULL, 'c', NULL, NULL),
  (2023, 117, NULL, '¿Cuál de estas intervenciones se considera, en la actualidad, de primera línea en el tratamiento de la anorexia nerviosa en personas adultas?:', 'Terapia Cognitiva Basada en Mindfulness (MBCT; Barnhofer et al., 2009).', 'Terapia Basada en la Mentalización (MBT; Bateman y Fonagy, 2004).', 'Motivational Enhancement Therapy (MET; Andersen et al., 2020).', 'Specialist Supportive Clinical Management (SSCM; McIntosh, 2015).', NULL, 'd', NULL, NULL),
  (2023, 118, NULL, '¿Cuál de estos aspectos debemos tener en cuenta en el tratamiento de los trastornos de la conducta alimentaria?:', 'En la bulimia nerviosa se evitará dar información sobre los mecanismos de regulación del peso y la nutrición para no aumentar la apetencia por alimentos prohibidos.', 'El tratamiento combinado (fármacos y psicoterapia) es la intervención que se ha mostrado más eficaz en el tratamiento tanto de la bulimia como de la anorexia nerviosa.', 'Eliminar o modificar la dieta no es un objetivo terapéutico en el tratamiento de la bulimia nerviosa porque los atracones dependen de aspectos emocionales.', 'Es habitual la falta de conciencia del problema, especialmente en la anorexia nerviosa, por lo que es recomendable incluir estrategias de motivación para el cambio.', NULL, 'd', NULL, NULL),
  (2023, 119, NULL, '¿Cuál sería, según el DSM-5, la especificación de gravedad para una persona con bulimia nerviosa que recurre a comportamientos compensatorios inapropiados un promedio de 10 veces por semana?:', 'Extremo.', 'Grave.', 'Moderado.', 'Leve.', NULL, 'b', NULL, NULL),
  (2023, 120, NULL, '¿Qué se puede afirmar con relación al curso de la anorexia nerviosa?:', 'Su inicio más común es en la primera infancia, sobre los ocho años.', 'Más de la mitad de las pacientes han tenido un diagnóstico previo de bulimia nerviosa.', 'La mortalidad se debe fundamentalmente a complicaciones médicas asociadas al propio trastorno o al suicidio.', 'Existe un segundo pico de incidencia, a partir de los 40 años, relacionado con la perimenopausia en mujeres.', NULL, 'c', NULL, NULL),
  (2023, 121, NULL, '¿Qué caracteriza a la anorexia nerviosa atípica según el DSM-5?:', 'Que se cumplen todos los criterios para la anorexia nerviosa, excepto que el peso del individuo está dentro o por encima del intervalo normal.', 'Que existe una regurgitación repetida de alimentos durante un periodo mínimo de un mes.', 'Purgas recurrentes para influir en el peso o la constitución en ausencia de atracones.', 'La evitación de la ingesta a causa de las características organolépticas de los alimentos.', NULL, 'a', NULL, NULL),
  (2023, 122, NULL, 'Con relación a las fobias específicas:', 'El aprendizaje vicario es la vía más relevante en la adquisición de las fobias.', 'Aproximadamente el 50% de personas diagnosticadas de fobia específica temen a más de una situación u objeto.', 'El miedo intenso y desproporcionado a la situación u objeto se acompaña de una cognición específica (ideación cognitiva).', 'Las fobias situacionales presentan una edad de inicio más tardía que el resto de fobias específicas.', NULL, 'd', NULL, NULL),
  (2023, 123, NULL, 'Según el modelo metacognitivo de Wells, ¿qué caracteriza a las personas con trastorno de ansiedad generalizada (TAG)?', 'Las creencias metacognitivas negativas y la preocupación tipo 2.', 'Las creencias metacognitivas positivas y la preocupación tipo 2.', 'Las creencias metacognitivas negativas y la preocupación tipo 1.', 'Las creencias metacognitivas positivas y la preocupación tipo 1.', NULL, 'a', NULL, NULL),
  (2023, 124, NULL, '¿Qué caracteriza a los sujetos con trastorno de ansiedad social (TAS)?:', 'Utilizan la supresión expresiva como estrategia de regulación emocional.', 'La ansiedad tiende a disminuir a lo largo del tiempo ya que están expuestos a constantes situaciones sociales en su día a día.', 'Acostumbran a subestimar las consecuencias negativas de las situaciones sociales.', 'Suelen iniciar tratamiento en fases iniciales del cuadro debido a las importantes limitaciones funcionales que conlleva.', NULL, 'a', NULL, NULL),
  (2023, 125, NULL, 'La edición más actual del programa de tratamiento para el control del pánico de Barlow se presenta estructurada en capítulos que se engloban en fases o módulos temáticos. ¿Qué capítulo NO forma parte de la fase “Habilidades de afrontamiento”?:', 'Entrenamiento en respiración.', 'Afrontando los síntomas físicos.', 'Estableciendo la jerarquía de situaciones agorafóbicas.', 'Estrategias cognitivas.', NULL, 'b', NULL, NULL),
  (2023, 126, NULL, '¿Cuál de las siguientes afirmaciones se corresponde con la terapia intensiva focalizada en las sensaciones de Baker-Morissette et al. (2005)?:', 'En la fase de preparación se entrena al paciente en técnicas de reducción de la activación.', 'Se dirige a pacientes con trastorno de pánico moderado-severo con o sin agorafobia.', 'El paciente se enfrenta desde el primer momento a las situaciones más temidas.', 'Una de las principales críticas hacia esta terapia es la ausencia de un módulo de prevención de recaídas.', NULL, 'c', NULL, NULL),
  (2023, 127, NULL, '¿Cuál de los siguientes componentes se incluye en la terapia cognitivo-conductual de Dugas y Robichaud para el abordaje del trastorno de ansiedad generalizada (TAG)?:', 'La exposición a la incertidumbre.', 'El entrenamiento en relajación.', 'La organización del tiempo.', 'La prevención de conductas de seguridad.', NULL, 'a', NULL, NULL),
  (2023, 128, NULL, 'Según la terapia integradora de Newman, ¿qué caracteriza a las personas con trastorno de ansiedad generalizada (TAG) y, por ende, se convierte en foco de tratamiento?:', 'La fusión con sus propias experiencias internas, como pensamientos o emociones.', 'La experimentación de emociones negativas de forma más fácil e intensa que la población general.', 'La mayor probabilidad de experimentar consecuencias interpersonales negativas.', 'La presencia de preocupaciones sobre los propios procesos cognitivos.', NULL, 'c', NULL, NULL),
  (2023, 129, NULL, '¿Qué módulo del Protocolo Unificado de Barlow et al. (2019) para el tratamiento transdiagnóstico de los trastornos emocionales tiene como objetivo descomponer las emociones en partes más manejables?:', 'Conciencia emocional plena.', 'Comprendiendo tus emociones.', 'Exposiciones emocionales.', 'Flexibilidad cognitiva.', NULL, 'b', NULL, NULL),
  (2023, 130, NULL, '¿Con qué nombre se conoce, en el proceso psicoterapéutico, a la interacción personal e íntima en la que el especialista en psicología clínica y su paciente se expresan de manera genuina, percibiéndose mutuamente tal y como se muestran, sin distorsiones?:', 'Transferencia.', 'Relación mutua.', 'Relación real.', 'Relación dual.', NULL, 'c', NULL, NULL),
  (2023, 131, NULL, '¿Cuál de las siguientes características ha demostrado asociarse con la variable conocida como “efectos del terapeuta”?:', 'La tendencia a confiar en el propio desempeño, acompañada de un sentido del self positivo.', 'La tendencia a dudar del propio desempeño, acompañada de un sentido del self negativo.', 'La tendencia a confiar en el propio desempeño, acompañada de un sentido del self negativo.', 'La tendencia a dudar del propio desempeño, acompañada de un sentido del self positivo.', NULL, 'd', NULL, NULL),
  (2023, 132, NULL, 'En psicoterapia, ¿qué tipo de preferencia correspondería a un paciente que expresa el deseo de que su psicólogo clínico le asigne tareas para realizar entre sesiones?:', 'Sobre las actividades.', 'Sobre el terapeuta.', 'Sobre el tratamiento.', 'Sobre el formato.', NULL, 'a', NULL, NULL),
  (2023, 133, NULL, '¿Cuál de las siguientes es una recomendación basada en la evidencia para el trabajo en psicoterapia con pacientes con un nivel de reactancia alto?:', 'Utilizar enfoques más directivos y estructurados.', 'Utilizar intervenciones paradójicas.', 'Provocar rupturas en la alianza de forma estratégica.', 'Derivar a terapia grupal.', NULL, 'b', NULL, NULL),
  (2023, 134, NULL, '¿Cuál de los siguientes aspectos fue propuesto por Frank (1961) como uno de los factores comunes a todas las psicoterapias eficaces?:', 'El manejo de la transferencia y la contratransferencia.', 'La monitorización sistemática de resultados.', 'La psicoeducación.', 'La activación de emociones intensas.', NULL, 'd', NULL, NULL),
  (2023, 135, NULL, '¿Cuál de las siguientes características NO es común en el síndrome confusional agudo?:', 'Desorientación temporal.', 'Alucinaciones hápticas.', 'Alteraciones del ciclo sueño-vigilia.', 'Alteraciones emocionales: agitación, agresividad, depresión, ansiedad, etc.', NULL, 'b', NULL, NULL),
  (2023, 136, NULL, 'Un paciente que presenta dificultad para mantener el estado de alerta, con conciencia limitada del entorno e irritabilidad, pero que es capaz de entender y ejecutar indicaciones puede presentar:', 'Sopor.', 'Estupor.', 'Obnubilación.', 'Coma.', NULL, 'c', NULL, NULL),
  (2023, 137, NULL, 'Un estado caracterizado por la disminución de la atención al entorno, la desorientación, la confusión en el curso del pensamiento y los automatismos involuntarios se corresponde con:', 'Los estados crepusculares.', 'Los estados oniroides.', 'El delirium.', 'El estupor.', NULL, 'a', NULL, NULL),
  (2023, 138, NULL, 'Un paciente comenta que, desde hace unos días, tiene una sensación extraña, como si algo hubiese cambiado y su entorno fuera diferente. ¿Qué fenómeno está experimentando?:', 'Estupor.', 'Desrealización.', 'Delirio nihilista.', 'Despersonalización.', NULL, 'b', NULL, NULL),
  (2023, 139, NULL, 'El concepto de perplejidad atencional hace referencia a:', 'La inestabilidad atencional y la dificultad para prestar atención a un estímulo.', 'La ausencia de atención a estímulos ante una gran concentración sobre alguna cuestión concreta.', 'La ausencia completa de disposición atencional.', 'La incapacidad para lograr la síntesis del contenido de la atención.', NULL, 'd', NULL, NULL),
  (2023, 140, NULL, 'Según la teoría basada en la mentalización, ¿qué característica se relaciona con el modo prementalizador simulado?:', 'El discurso puede parecer vacío, carente de significado, inconsecuente y circular.', 'Entendimiento de los demás y de uno mismo desde el punto de vista de las conductas físicas.', 'La dimensión interna tiene el mismo poder que la externa, se siente que los pensamientos son reales.', 'Focalización extrema en lo externo.', NULL, 'a', NULL, NULL),
  (2023, 141, NULL, 'Un paciente que acude a un dispositivo de atención a las drogodependencias explica, en la primera entrevista, haber sido derivado porque en el último examen médico le detectaron parámetros indicativos de daño hepático por consumo excesivo de alcohol. Se muestra sorprendido ante la derivación ya que refiere que su círculo social tiene el mismo patrón de consumo que él. ¿En qué etapa del cambio es probable que se encuentre el paciente?:', 'Precontemplación.', 'Contemplación.', 'Acción.', 'Recaída.', NULL, 'a', NULL, NULL),
  (2023, 142, NULL, 'Según la tipología del DSM-5, cuando se producen dos o más episodios de insomnio con una duración igual o superior a los tres meses en el plazo de un año lo clasificaremos como:', 'Insomnio persistente.', 'Insomnio recurrente.', 'Insomnio agudo.', 'Insomnio intermedio.', NULL, 'b', NULL, NULL),
  (2023, 143, NULL, '¿En cuál de los siguientes trastornos los pacientes presentan movimientos vigorosos o violentos durante el sueño MOR, que suelen representar “escenificaciones” de los ensueños propios de esta fase, período en el que normalmente se presenta una atonía muscular?:', 'Pesadillas asociadas al sueño MOR.', 'Trastorno de conducta asociado al sueño MOR.', 'Terrores nocturnos asociado al sueño MOR.', 'Sonambulismo asociado al sueño MOR.', NULL, 'b', NULL, NULL),
  (2023, 144, NULL, 'Una paciente de 14 años inicia tratamiento psicológico. Presenta un historial de comportamiento desafiante hacia los profesores y hacia sus padres. La paciente ha tenido episodios en los que agredió a dos compañeras de la escuela y en una ocasión rompió un pupitre tirándolo por las escaleras. Ha sido expulsada varias veces. En consulta observamos que no parece estar triste o irritada y que miente y niega lo sucedido. Los padres indican que ha empezado a robarles dinero a escondidas. ¿Cuál es el diagnóstico, según el DSM-5?:', 'Psicopatía.', 'Trastorno explosivo intermitente.', 'Trastorno de conducta.', 'Trastorno negativista desafiante.', NULL, 'c', NULL, NULL),
  (2023, 145, NULL, '¿Cuál de las siguientes afirmaciones es CORRECTA respecto a los terrores nocturnos?:', 'Se producen durante el sueño MOR.', 'Se producen hacia la mitad y el final de la noche.', 'Suelen cursar con estados crepusculares.', 'Se producen signos de alerta autónoma, como midriasis o taquipnea.', NULL, 'd', NULL, NULL),
  (2023, 146, NULL, '¿En qué disfunción sexual el tratamiento suele incluir entrenamiento del músculo pubocoxígeo con técnicas de autoestimulación?:', 'Eyaculación retardada.', 'Trastorno eréctil.', 'Trastorno orgásmico femenino.', 'Trastorno por dolor genitopélvico/penetración.', NULL, 'c', NULL, NULL),
  (2023, 147, NULL, 'Señale a qué concepto de la práctica de la psicoterapia se refiere Clara Hill (2017) con la expresión “la manifestación de los niveles más altos de habilidad, destreza, competencia profesional y efectividad”:', 'Práctica deliberada.', 'Práctica reflexiva.', 'Pericia clínica.', 'Rendimiento terapéutico.', NULL, 'c', NULL, NULL),
  (2023, 148, NULL, 'Dentro del marco de la Terapia de Esquemas, ¿cuál de las siguientes respuestas hace mención a alguna de las 5 dimensiones de esquemas que propone J. Young en su modelo?:', 'Dimensión de desconexión y rechazo.', 'Dimensión de la necesidad del sí mismo.', 'Dimensión del proceso elaborativo interrumpido.', 'Dimensión de alienación y apatía.', NULL, 'a', NULL, NULL),
  (2023, 149, NULL, 'Señale cuál de las siguientes afirmaciones es CORRECTA con respecto a la descripción del trastorno de juego por internet realizada en el DSM-5:', 'Se refiere a la adicción a los juegos de azar a través de internet.', 'Se refiere al uso persistente y recurrente de internet para participar en juegos, que llega a provocar un malestar clínicamente significativo.', 'Se considera que existe evidencia suficiente para considerarlo dentro de los diagnósticos oficiales de trastornos mentales.', 'Ha sido incluido dentro de la categoría “Adicciones conductuales”, junto con otros trastornos adictivos que no implican sustancias.', NULL, 'b', NULL, NULL),
  (2023, 150, NULL, 'En relación con las diferencias en el juego patológico en función del género:', 'Las mujeres empiezan a jugar antes.', 'Las mujeres suelen tener más trastornos afectivos comórbidos.', 'Los varones presentan una mayor comorbilidad con el abuso de benzodiacepinas.', 'No se han encontrado diferencias en cuanto a la modalidad de juego.', NULL, 'b', NULL, NULL),
  (2023, 151, NULL, 'En relación con el Síndrome de Fregoli:', 'La variante opuesta es el denominado Síndrome de Clérambault.', 'El paciente cree que una persona importante en su vida está siendo usurpada por un impostor que tiene exactamente la misma apariencia.', 'Es un falso reconocimiento positivo.', 'Es una paramnesia del recuerdo.', NULL, 'c', NULL, NULL),
  (2023, 152, NULL, 'Según el DSM-5, en el curso de un trastorno depresivo mayor, ¿qué condiciones son necesarias para considerar que el paciente se encuentra en una fase de remisión total?:', 'Una reducción de más de un 50% de la gravedad de los síntomas respecto a la línea base.', 'Remisión de los síntomas durante más de seis meses y retorno al funcionamiento normal.', 'Cese significativo de los signos y síntomas durante los últimos dos meses.', 'Presencia de síntomas menores, sin llegar a cumplir todos los criterios diagnósticos, durante un período menor a dos meses desde el inicio del episodio depresivo mayor.', NULL, 'c', NULL, NULL),
  (2023, 153, NULL, '¿Cuál de las siguientes teorías sobre la depresión señala la especial importancia del papel de las rumiaciones como factor de mayor gravedad y duración de los síntomas depresivos?:', 'La teoría cognitiva de Beck.', 'La teoría de la desesperanza de Abramson.', 'La teoría conductual de Ferster.', 'La teoría de los estilos de respuesta de Nolen-Hoeksema.', NULL, 'd', NULL, NULL),
  (2023, 154, NULL, 'Señala la respuesta CORRECTA con respecto al diagnóstico diferencial entre los trastornos bipolares y los trastornos depresivos:', 'El trastorno bipolar tiene una aparición más tardía, en torno a los 30 años, mientras que la depresión aparece alrededor de los 20 años.', 'Existe mayor probabilidad de sufrir síntomas atípicos, como enlentecimiento motor, agitación e hipersomnia, en las depresiones bipolares que en las unipolares.', 'Existe mayor probabilidad de suicidio en las depresiones unipolares.', 'Existe mayor probabilidad de abuso de sustancias psicoactivas en depresiones unipolares.', NULL, 'b', NULL, NULL),
  (2023, 155, NULL, '¿A qué nos referimos con aquellas actividades realizadas por el psicólogo clínico o el psicólogo interno residente con esfuerzo sistemático, que se focalizan en la mejora del rendimiento propio, que se realizan durante extensos períodos de tiempo, con la guía de un mentor que proporciona feedback inmediato sobre la ejecución y que promueven progresivamente una mejora de la práctica de la psicoterapia mediante la repetición y el refinamiento sucesivo?:', 'A la práctica reflexiva.', 'A la práctica deliberada.', 'A la práctica continuada.', 'A las habilidades de facilitación interpersonal.', NULL, 'b', NULL, NULL),
  (2023, 156, NULL, 'Según la Terapia Cognitiva de Beck et al. (1979) para el tratamiento de la depresión, ¿cuál de las siguientes técnicas para promover el cambio de pensamientos automáticos corresponde a la categoría de técnica de tipo cognitivo?:', 'Análisis de responsabilidad.', 'Role-playing.', 'Distracción externa.', 'Técnica de reatribución.', NULL, 'd', NULL, NULL),
  (2023, 157, NULL, '¿Cuál de estas afirmaciones es INCORRECTA en relación con el trastorno bipolar?:', 'En la etiología del trastorno bipolar intervienen los factores constitucionales.', 'Los gemelos idénticos con un trastorno bipolar pueden llegar a tener una propensión de hasta el 50% de padecer el mismo trastorno.', 'El estrés situacional puede ser el disparador de un episodio maniaco.', 'Pequeñas alteraciones en el ciclo de sueño pueden afectar adversamente a las personas que muestran predisposición hacia los trastornos de tipo bipolar.', NULL, 'b', NULL, NULL),
  (2023, 158, NULL, '¿Cómo se denomina el delirio en el que la persona cree que su piel está infectada por bichos o parásitos y que suele acompañarse de alucinaciones táctiles o somáticas?:', 'Síndrome de Cotard.', 'Síndrome de Otelo.', 'Síndrome de Ekbom.', 'Síndrome de Fregoli.', NULL, 'c', NULL, NULL),
  (2023, 160, NULL, '¿Cuál de los siguientes trastornos del pensamiento hace referencia a un trastorno formal del pensamiento?:', 'Esquizofasia.', 'Pensamientos automáticos negativos.', 'Obsesión.', 'Preocupaciones.', NULL, 'a', NULL, NULL),
  (2023, 161, NULL, 'Se considera un trastorno formal del pensamiento de tipo negativo:', 'Incoherencia.', 'Pérdida de meta.', 'Alogia.', 'Resonancia.', NULL, 'c', NULL, NULL),
  (2023, 162, NULL, 'Indica la afirmación INCORRECTA en relación con la terapia cognitivo-conductual para la psicosis:', 'Cuando trabajamos el significado de los síntomas, el objetivo es normalizar la experiencia psicótica conceptualizando el delirio como un intento de encontrar sentido a una serie de experiencias extrañas.', 'En la fase de identificación de los pensamientos y emociones asociados a los episodios psicóticos podemos aplicar estrategias como la desdramatización y el análisis de las ventajas e inconvenientes de mantener la creencia delirante.', 'Para finalizar el trabajo con una creencia, es recomendable poner a prueba también la alternativa no delirante, ideando para ello otra prueba de realidad.', 'Ha sido incluida en la mayoría de las guías de práctica clínica como el tratamiento psicológico de elección para la psicosis.', NULL, 'b', NULL, NULL),
  (2023, 163, NULL, 'De las siguientes intervenciones psicológicas para la psicosis, ¿cuál de ellas presenta un nivel de evidencia y un grado de recomendación menor?:', 'Terapia cognitivo-conductual para la psicosis.', 'Intervención familiar.', 'Tratamiento asertivo comunitario.', 'Terapias contextuales.', NULL, 'd', NULL, NULL),
  (2023, 164, NULL, 'En relación con la terapia cognitivo conductual aplicada a los delirios:', 'La comprobación empírica es más efectiva cuando se aplica después de la fase de análisis verbal y no antes.', 'El trabajo con el significado de los esquemas cognitivos puede realizarse independientemente del insight del paciente.', 'Las fases del análisis verbal de una creencia son dos, analizar las evidencias y la lógica interna del delirio.', 'Cuando iniciamos una intervención sobre una idea delirante, es muy importante cuestionar directamente dicha creencia, ya que se ha demostrado que reduce la resistencia al cambio.', NULL, 'a', NULL, NULL),
  (2023, 165, NULL, '¿Cuál es el objetivo del trabajo con esquemas cognitivos básicos en pacientes con voces persistentes?:', 'Trabajar los factores de vulnerabilidad previos al inicio del trastorno.', 'Mejorar las estrategias de afrontamiento de las alucinaciones.', 'Prevenir el desarrollo de interpretaciones deliroides.', 'Mejorar el funcionamiento social.', NULL, 'a', NULL, NULL),
  (2023, 166, NULL, '¿Qué funciones tiene el psicólogo clínico en la administración de la terapia AVATAR para el tratamiento de las alucinaciones auditivas resistentes a la medicación?:', 'El terapeuta no tiene funciones específicas puesto que se trata de una intervención digital autoadministrada.', 'El terapeuta no tiene funciones específicas puesto que se trata de una intervención basada en realidad virtual y, por tanto, autoadministrada.', 'Ser capaz de representar de manera veraz el carácter y el papel de la voz en relación con la persona que presenta las voces.', 'Enfrentarse directamente a la voz con maestría.', NULL, 'c', NULL, NULL),
  (2023, 167, NULL, '¿Cuál de los siguientes es el aspecto fundamental en el que se basa la terapia basada en la mentalización para niños (MBT-C)?:', 'La resolución de problemas.', 'Las defensas del yo.', 'La teoría del apego.', 'El desarrollo del insight.', NULL, 'c', NULL, NULL),
  (2023, 168, NULL, 'Señale un ejemplo del uso de la técnica de la externalización en niños y adolescentes:', 'Hablar de la anorexia como una sombra malvada.', 'Reflexionar sobre los apoyos externos de los que dispone el niño o adolescente.', 'Dibujar un futuro mejor en el que no exista el problema.', 'Trabajar sólo con los padres cuando el niño o adolescente no esté motivado por solucionar el problema.', NULL, 'a', NULL, NULL),
  (2023, 169, NULL, 'Según el DSM-5, ¿cuál se corresponde con el trastorno de la comunicación social (pragmático)?:', 'Dificultad persistente en la producción fonológica que interfiere con la comunicación verbal de mensajes.', 'Dificultad persistente en el uso social de la comunicación verbal y no verbal.', 'Alteraciones persistentes en la comunicación verbal, como por ejemplo la repetición de sonidos y sílabas, que dificultan la conversación.', 'Los síntomas suelen identificarse en la adolescencia tardía, ya que es cuando las interacciones sociales empiezan a ser más complejas.', NULL, 'b', NULL, NULL),
  (2023, 170, NULL, 'Señale la INCORRECTA. Según el DSM-5, la discapacidad intelectual:', 'Incluye limitaciones en el funcionamiento intelectual y en el comportamiento adaptativo.', 'Las deficiencias intelectuales comienzan durante el período de desarrollo.', 'Puede incluir la alteración de funciones como el razonamiento, la resolución de problemas, la planificación o el pensamiento abstracto.', 'Debe medirse siempre mediante pruebas estandarizadas individualizadas y obtenerse un Cociente Intelectual Total de 70 o inferior.', NULL, 'd', NULL, NULL),
  (2023, 171, NULL, 'El trastorno de apego reactivo y el trastorno de relación social desinhibida (según el DSM-5) tienen en común que los menores:', 'Presentan un comportamiento verbal o físico demasiado familiar y acusada incapacidad para manifestar vínculos selectivos apropiados.', 'Tienen relaciones sociales, en la mayor parte de los contextos, sumamente alteradas e inadecuadas para su nivel de desarrollo (a partir de los 3 años de edad).', 'Han sufrido negligencia o carencia social que se manifiesta por la falta persistente de tener cubiertas las necesidades emocionales básicas por parte de los cuidadores adultos.', 'Presentan episodios de irritabilidad, tristeza o miedo inexplicado que son evidentes, incluso durante las interacciones no amenazadoras con los cuidadores adultos.', NULL, 'c', NULL, NULL),
  (2023, 172, NULL, 'Señala la respuesta CORRECTA con respecto a la terapia de Desensibilización y Reprocesamiento por Movimientos Oculares (EMDR) para el tratamiento psicológico en población infantojuvenil:', 'No existe un protocolo estandarizado de aplicación específico para esta población.', 'Únicamente se puede aplicar la estimulación bilateral mediante tapping.', 'Se pueden emplear en su aplicación recursos como el dibujo.', 'No es relevante que el entorno familiar participe en esta terapia.', NULL, 'c', NULL, NULL),
  (2023, 173, NULL, 'En relación con el trastorno negativista desafiante:', 'Las estrategias negativas (como castigos) y aquellas que priman el control aparecen con más frecuencia en familias de menores con este diagnóstico.', 'Los hallazgos biológicos pueden explicar la variabilidad individual que se produce en torno a este diagnóstico.', 'Sólo el 10% de las personas diagnosticadas de TDAH desarrollarán de forma comórbida un trastorno negativista.', 'El tratamiento “The Incredible Years” aún no tiene la suficiente evidencia empírica.', NULL, 'a', NULL, NULL),
  (2023, 175, NULL, 'La terapia basada en la familia (FBT) es un tipo de tratamiento que integra técnicas de distintas escuelas sistémicas y que se emplea en casos de trastornos alimentarios. Este tratamiento:', 'Tiene evidencia empírica suficiente en el tratamiento de la anorexia nerviosa en población infantil y adolescente.', 'Genera menos mejoría en pacientes con mayor gravedad al inicio del tratamiento.', 'Implica integrar el trastorno en la identidad del paciente para aumentar la conciencia de enfermedad.', 'No supone la participación de un equipo multidisciplinar.', NULL, 'a', NULL, NULL),
  (2023, 176, NULL, 'Según la Society for Clinical Child and Adolescent Psychology (División 53, Asociación Americana de Psicología) es un tratamiento bien establecido (nivel 1) para el tratamiento del TDAH en la infancia y adolescencia:', 'Neurofeedback.', 'Entrenamiento cognitivo.', 'Entrenamiento conductual para padres en preescolares.', 'Terapia basada en el control de las emociones en adolescentes.', NULL, 'c', NULL, NULL),
  (2023, 177, NULL, 'Entre las intervenciones psicológicas utilizadas en niños con trastorno del espectro autista, ¿cuál es la que tiene mayor grado de recomendación (grado A), según los criterios utilizados en las Guías de Práctica Clínica del Sistema Nacional de Salud Español?:', 'Intervención naturalista conductual en desarrollo.', 'Intervención conductual intensiva temprana.', 'Entrenamiento en habilidades sociales.', 'Intervención temprana basada en familias.', NULL, 'a', NULL, NULL),
  (2023, 178, NULL, 'En niños con trastorno del espectro autista, existe una intervención conductual que busca aumentar la iniciativa hacia el aprendizaje, incrementando dimensiones centrales como la motivación, conducta autodirigida, iniciación en la conducta social o diversificación de intereses. ¿Cómo se denomina dicha intervención?:', 'Entrenamiento en conductas generales de aprendizaje.', 'Entrenamiento en conductas concretas de aprendizaje.', 'Entrenamiento en conductas pivotales de aprendizaje.', 'Entrenamiento en conductas básicas de aprendizaje lector.', NULL, 'c', NULL, NULL),
  (2023, 179, NULL, 'La intervención psicológica comprensiva conductual para los tics (CBIT) NO incluye:', 'El entrenamiento en inversión del hábito.', 'El entrenamiento en relajación.', 'La intervención contextualizada y funcional para ver situaciones asociadas a los tics.', 'La práctica negativa masiva para los tics.', NULL, 'd', NULL, NULL),
  (2023, 180, NULL, 'Señale la terapia con mayor nivel de evidencia y grado de recomendación para el manejo de las autolesiones en adolescentes:', 'Psicoterapia individual para adolescentes (IPT-A).', 'Terapia dialéctico conductual para adolescentes (DBT-A).', 'Terapia cognitivo conductual integrada (I-CBT).', 'Terapia basada en la mentalización para adolescentes (MBT-A).', NULL, 'b', NULL, NULL),
  (2023, 181, NULL, 'El modelo terapéutico transdiagnóstico Group Behavioral Activation Therapy (GBAT), NO entrena alguna de las siguientes dimensiones:', 'Psicoeducación sobre la ansiedad y la depresión.', 'Evaluación funcional e identificación del papel de la evitación.', 'Solución de problemas y toma de decisiones.', 'Psicoeducación conductual sobre trastornos del comportamiento.', NULL, 'd', NULL, NULL),
  (2023, 182, NULL, 'El duelo complicado durante la infancia y la adolescencia:', 'No se puede diagnosticar antes de los 5 años ya que a esa edad todavía no tienen una idea clara de lo que es la muerte.', 'Un factor protector es que el cuidador principal realice su propio proceso de duelo de forma adecuada.', 'El tratamiento para los duelos traumáticos tiene como principal componente la exposición en vivo.', 'En la adolescencia las conductas regresivas son uno de los síntomas principales del duelo complicado.', NULL, 'b', NULL, NULL),
  (2023, 183, NULL, 'En el tratamiento del mutismo selectivo, debemos tener en cuenta que:', 'Existen tratamientos bien establecidos para este diagnóstico.', 'La terapia sistémica es la primera elección.', 'Los estudios de caso único son los más predominantes en la literatura científica en cuanto al tratamiento de este trastorno.', 'La Integrated Behaviour Therapy for Selective Mutism (IBTSM; Bergman et al., 2013) es una terapia que se basa en una orientación psicodinámica y que es específica para este trastorno.', NULL, 'c', NULL, NULL),
  (2023, 184, NULL, 'El trastorno de estrés postraumático durante la infancia y la adolescencia:', 'Presenta una prevalencia mucho más baja que durante la edad adulta.', 'Las pesadillas que se presentan durante la infancia pueden tener un contenido inespecífico, no relacionado con el hecho traumático.', 'No hay diferencias de sintomatología en cuanto al género, éstas aparecen durante la adolescencia y la vida adulta.', 'En el DSM-5 se incluyen diferencias para el diagnóstico en menores de 10 años.', NULL, 'b', NULL, NULL),
  (2023, 185, NULL, 'Una niña de 10 años acude a su centro de salud mental porque, desde hace 6 meses, presenta recuerdos intrusivos, pesadillas, hipervigilancia y evitación de recuerdos asociados a un reciente accidente de tráfico que ha sufrido. Para el tratamiento deberíamos tener en cuenta que:', 'No existen tratamientos con suficiente grado de recomendación para este diagnóstico en la infancia y adolescencia.', 'En la primera fase de tratamiento deberíamos aplicar exposición en imaginación al acontecimiento traumático.', 'La práctica de técnicas de relajación es una de las últimas fases del tratamiento.', 'La primera fase del tratamiento incluye psicoeducación sobre los síntomas que sufre.', NULL, 'd', NULL, NULL),
  (2023, 186, NULL, 'En relación con la violencia sexual sufrida durante la infancia y la adolescencia:', 'Se estima que entre un 40-50% de los menores ha sufrido algún tipo de abuso sexual.', 'Como profesionales de la salud mental necesitamos primero el consentimiento de los progenitores para notificar una revelación de violencia sexual infantil por parte de un menor.', 'Está asociada, en todos los casos, a psicopatología durante la edad adulta.', 'Como profesionales de la salud mental estamos siempre obligados a notificar una revelación de violencia sexual infantil por parte de un menor.', NULL, 'd', NULL, NULL),
  (2023, 187, NULL, 'La técnica de tratamiento del lenguaje infantil que consiste en responder a las verbalizaciones del niño ampliándolas de algún modo para proporcionar un nuevo modelo de enunciado, se denomina:', 'Pensamiento en voz alta.', 'Recast o reformulación conversacional.', 'Habla paralela.', 'Estimulación focalizada.', NULL, 'b', NULL, NULL),
  (2023, 188, NULL, '¿Cuál de las siguientes conductas se corresponde con una manifestación temprana de alerta para detectar el trastorno del espectro del autismo entre los 12 y los 18 meses de edad?:', 'Dificultad para comprender las normas sociales.', 'Inversión pronominal.', 'Falta de atención conjunta.', 'Dificultad para comprender dobles sentidos.', NULL, 'c', NULL, NULL),
  (2023, 189, NULL, '¿Cuál de las siguientes intervenciones para los trastornos del espectro del autismo se considera como un tratamiento eficaz, con al menos un nivel de evidencia 1+?:', 'Programa TEACCH (Treatment and Education of Autistic Related Communication Handicapped Children).', 'Programa PECS (Picture Exchange Communication System).', 'Modelo DIR (Developmental, Individual Difference, Relationship).', 'Modelo Denver (Early Start Denver Model).', NULL, 'd', NULL, NULL),
  (2023, 190, NULL, 'Según las recomendaciones de la Guía NICE (2019) para el abordaje de la depresión en niños y adolescentes:', 'En los casos de menores entre 12-18 años con un trastorno depresivo moderado-grave, se recomienda ofrecer Terapia Cognitivo-Conductual individual durante al menos 3 meses.', 'En los casos de menores de 5 años con un trastorno depresivo moderado-grave, la elección del tratamiento se recomienda que se lleve a cabo según el criterio del facultativo, sin tener en cuenta las preferencias del menor y los cuidadores.', 'En los casos de menores con depresión leve, si precisan tratamiento farmacológico, se recomienda la fluoxetina.', 'En el caso de menores de 5-11 años con un trastorno depresivo moderado-grave, no se recomienda la psicoterapia de orientación psicodinámica, dado que aún no se ha desarrollado la suficiente capacidad de introspección que permita obtener resultados positivos.', NULL, 'a', NULL, NULL),
  (2023, 191, NULL, 'En el trastorno bipolar en niños y adolescentes, un episodio de hipomanía tiene una duración de:', '3 días.', '4 días.', '5 días.', 'Al menos una semana.', NULL, 'b', NULL, NULL),
  (2023, 192, NULL, 'Según el modelo de actitudes unitario de Thurstone (1931), ¿cómo se entienden las actitudes?:', 'Como la actitud implícita o explícita hacia un objeto psicológico.', 'Como la actitud deliberada o automática hacia un objeto psicológico.', 'Como el grado de afecto positivo o negativo hacia un objeto psicológico.', 'Como la actitud objetiva o subjetiva hacia un objeto psicológico.', NULL, 'c', NULL, NULL),
  (2023, 193, NULL, '¿Cómo explicaría la teoría de la identidad social que un individuo pueda seguir órdenes del líder sin cuestionar su validez?:', 'Porque se trata de un individuo despersonalizado o con una identidad personal baja.', 'Porque la prominencia de la identidad social es baja.', 'Porque su autoconcepto personal difiere considerablemente del miembro prototipo del grupo.', 'Porque tiene una autoconciencia pública baja.', NULL, 'a', NULL, NULL),
  (2023, 194, NULL, '¿A qué hace referencia la influencia social normativa?:', 'A la tendencia a aceptar la información de los demás como prueba acerca de la realidad.', 'A la tendencia a ser diferenciado de otros en algunos aspectos.', 'A la tendencia a avenirse a cumplir con las expectativas de los demás para obtener aprobación social.', 'A la tendencia a avenirse a las normas de un grupo que lo define a uno como miembro.', NULL, 'c', NULL, NULL),
  (2023, 195, NULL, '¿Qué es la complacencia inducida?:', 'Un tipo de disonancia cognitiva.', 'Un tipo de desindividuación.', 'Un tipo de reciprocidad.', 'Un tipo de dilema social.', NULL, 'a', NULL, NULL),
  (2023, 196, NULL, '¿Cómo se denomina al heurístico según el cual cuanto más fácil un estímulo recupera un evento de la memoria, más se tiende a pensar que hay muchos eventos como ese relacionados con aquel estímulo?:', 'Heurístico de representatividad.', 'Heurístico de ajuste.', 'Heurístico de disponibilidad.', 'Heurístico de anclaje.', NULL, 'c', NULL, NULL),
  (2023, 197, NULL, '¿Qué dimensiones identificó Hofstede (1980) en su primer modelo de clasificación de culturas?:', 'Distancia de poder, evitación de incertidumbre, masculinidad-feminidad, individualismo-colectivismo.', 'Apertura al cambio versus conservadurismo y superación personal versus autotrascendencia.', 'Cooperación, competencia e identidad social.', 'Ideología grupal (comparativa versus no comparativa) y orientación de valores (colectivista versus individualista).', NULL, 'a', NULL, NULL),
  (2023, 198, NULL, '¿Qué tres dimensiones causales principales propone la teoría de la atribución causal de Weiner?:', 'Distintividad, consensualidad y consistencia.', 'Locus, estabilidad y controlabilidad.', 'Disposicionales, situacionales y culturales.', 'Personales/ambientales, globales/específicas y duraderas/temporales.', NULL, 'b', NULL, NULL),
  (2023, 199, NULL, '¿Cuál de las siguientes afirmaciones sobre la conducta prosocial es CORRECTA?:', 'La conducta prosocial puede ser altruista o no altruista.', 'La conducta prosocial no implica riesgo para quien la lleva a cabo.', 'La conducta prosocial está positivamente correlacionada con el número de espectadores presentes en una emergencia.', 'La presencia de otro espectador que ayude inhibe la propia conducta prosocial.', NULL, 'a', NULL, NULL),
  (2023, 200, NULL, 'En el estudio de los prejuicios, ¿cómo se denomina a la tendencia a sobreestimar la proporción de comportamientos negativos en grupos relativamente pequeños?:', 'Efecto priming.', 'Diferenciación del exogrupo.', 'Efecto Pygmalion.', 'Correlaciones ilusorias.', NULL, 'd', NULL, NULL),
  (2023, 201, NULL, '¿Cuál de los siguientes es un criterio diagnóstico del Trastorno de Atracones según el DSM-5?:', 'La autoevaluación está indebidamente influida por la constitución y el peso corporal.', 'Los atracones se producen, de promedio, al menos una vez a la semana durante tres meses.', 'El atracón se asocia a la presencia recurrente de un comportamiento compensatorio inapropiado.', 'Los atracones se producen, de promedio, al menos dos veces a la semana durante dos meses.', NULL, 'b', NULL, NULL),
  (2023, 202, NULL, '¿Cuál de los siguientes Trastornos NO se considera en el DSM-5 dentro de los “Trastornos disruptivos, del control de los impulsos y de la conducta”?:', 'Trastorno negativista desafiante.', 'Juego patológico.', 'Piromanía.', 'Cleptomanía.', NULL, 'b', NULL, NULL),
  (2023, 203, NULL, 'La etapa 3 de la Terapia Dialéctico-Conductual se centra en:', 'Reemplazar la “desesperación silenciosa” por la experiencia emocional no traumática.', 'Adquirir control sobre la propia conducta.', 'Resolver la sensación de no estar completo y desarrollar libertad.', 'Adquirir felicidad e infelicidad “ordinarias” y reducir los problemas de la vida de la persona.', NULL, 'd', NULL, NULL),
  (2023, 204, NULL, '¿Cuál de las siguientes terapias para el trastorno límite de la personalidad tiene un formato exclusivamente grupal?:', 'STEPPS.', 'Terapia Dialéctico-Conductual.', 'Terapia Cognitivo-Interpersonal.', 'Terapia Cognitivo-Analítica.', NULL, 'a', NULL, NULL),
  (2023, 205, NULL, 'Según la entrevista motivacional, cuando un paciente con adicción está ambivalente hacia el cambio, debemos:', 'Realizar un balance decisional.', 'Evitar el reflejo de corrección.', 'Darle argumentos a favor del cambio.', 'Señalarle sus defensas o resistencias.', NULL, 'b', NULL, NULL),
  (2023, 206, NULL, '¿Cuál de los siguientes acrónimos se utiliza en el Protocolo Unificado para el Tratamiento Transdiagnóstico de los Trastornos Emocionales?:', 'ABC.', 'ARCO.', 'TIP.', 'CCR1.', NULL, 'b', NULL, NULL),
  (2023, 207, NULL, 'El concepto clásico de alucinación pálida descrito por Griesinger en 1845, ¿a qué concepto actual haría referencia?:', 'Pseudoalucinación.', 'Pseudopercepciones.', 'Anomalía en la intensidad de los estímulos, una distorsión perceptiva.', 'Hipoestesia, un engaño perceptivo.', NULL, 'a', NULL, NULL),
  (2023, 208, NULL, '¿Qué tipo de creencias sobre las voces aborda el modelo de Chadwick, Birchwood y Trower (1996)?:', 'Creencias sobre el origen de las voces.', 'Creencias esquemáticas nucleares.', 'Creencias sobre el poder, la identidad y el propósito de las voces.', 'Este modelo no se centra de forma primaria en las creencias.', NULL, 'c', NULL, NULL),
  (2023, 209, NULL, '¿En qué intervención se enseña a los niños “habilidades de detective” para resolver los misterios de sus emociones?:', 'Super Skills For Life.', 'The Coping Koala.', 'Take ACTION.', 'Protocolo Unificado para niños.', NULL, 'd', NULL, NULL),
  (2023, 210, NULL, 'En relación con la discapacidad intelectual:', 'La intervención debe basarse en modelos médicos, psicométricos y psicopatológicos.', 'El enfoque más adecuado consiste en la adopción de un modelo funcional, de orientación cognitivo-conductual.', 'Los apoyos y su intensidad se determinan de acuerdo a baremos establecidos según la gravedad o el nivel de discapacidad.', 'El enfoque más adecuado consiste en realizar una valoración normativa, con pruebas de rendimiento objetivas, para valorar el potencial de las personas con discapacidad.', NULL, 'b', NULL, NULL);
